    await page.goto(baseUrl);

    await expect(page.getByTestId("main-menu-trigger")).toBeVisible();
    await expect(page.getByTestId("command-palette-button")).toBeHidden();

    await page.getByTestId("main-menu-trigger").click();

    await expect(page.getByTestId("command-palette-button")).toHaveText("Command paletteCtrl+/");
    await expect(page.getByTestId("command-palette-button")).toHaveClass("radix-menu-item dropdown-menu-item dropdown-menu-item-base highlighted primary");

    await expect(page.getByTestId("help-menu-item")).toBeHidden();

